
from interops.libraries.mosaiq.interactions.objects.mosaiq_core_objects import MosaiqCoreObjects
from interops.libraries.mosaiq.interactions.objects.mosaiq_register_objects import MosaiqRegisterObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME

def __find_reg_window(objectMap: dict) -> bool:
    """find if new window appearing

    :return: True or False
    :rtype: bool
    """
    return CommonActions.wait_for_object_to_appear(objectMap)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_register_from_help() -> bool:
    """opens a register window from help->about->opens a register pane

    :return: True or False
    :rtype: bool
    """
    CommonActions.left_click_object(MosaiqCoreObjects.menuBar_Item_Help)
    CommonActions.left_click_object(MosaiqCoreObjects.help_MenuItem_About)
    return True if __find_reg_window(MosaiqRegisterObjects.register_About_Pane) is None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def generate_a_key() -> None:
    """generates a key with register button-> press Alt+g -> click on generate key - >waits until the new register window appeares ->clicks on Yes

    :return: None
    :rtype: None
    """
    CommonActions.left_click_object(MosaiqRegisterObjects.register_Button)
    if __find_reg_window(MosaiqRegisterObjects.register_Pane):
        CommonActions.press_key_sequence("<Alt+g>")
        CommonActions.left_click_object(MosaiqRegisterObjects.register_Generate_Reg_Key_Button)

    if __find_reg_window(MosaiqRegisterObjects.registration_New_Window):
        CommonActions.left_click_object(MosaiqRegisterObjects.registration_New_Yes_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_Auth(keytoEnter: str) -> None:
    """Enter text in Authorization edit and click on Ok

    :return: None
    :rtype: None
    """
    CommonActions.type_in_textfield(MosaiqRegisterObjects.register_Authorization_Key_Edit,keytoEnter)
    CommonActions.left_click_object(MosaiqRegisterObjects.register_Ok_Button)